const listWorkflowArtifactCleanup = `-- name: ListWorkflowArtifactCleanup :many
SELECT id, workspace_id, workflow_instance_id, storage_key, status, expires_at, created_at FROM workflow_artifact_upload
WHERE status IN ('deleting','pending') AND expires_at <= now()
ORDER BY expires_at LIMIT 100
`

// System storage reconciliation also handles tombstones after workspace deletion.
func (q *Queries) ListWorkflowArtifactCleanup(ctx context.Context) ([]WorkflowArtifactUpload, error) {
	rows, err := q.db.Query(ctx, listWorkflowArtifactCleanup)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WorkflowArtifactUpload{}
	for rows.Next() {
		var i WorkflowArtifactUpload
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.WorkflowInstanceID,
			&i.StorageKey,
			&i.Status,
			&i.ExpiresAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listWorkflowResultArtifacts = `-- name: ListWorkflowResultArtifacts :many
SELECT revision.id, revision.workspace_id, revision.workflow_instance_id, revision.artifact_id, revision.execution_id, revision.result_id, revision.upload_id, revision.revision, revision.source_attachment_id, revision.kind, revision.media_type, revision.schema_version, revision.checksum, revision.size_bytes, revision.created_at, artifact.name, upload.storage_key
FROM workflow_artifact_revision AS revision
JOIN workflow_artifact AS artifact ON artifact.id=revision.artifact_id AND artifact.workspace_id=revision.workspace_id
JOIN workflow_artifact_upload AS upload ON upload.id=revision.upload_id AND upload.workspace_id=revision.workspace_id AND upload.status='committed'
WHERE revision.workspace_id=$1 AND revision.result_id=$2 ORDER BY artifact.name
`

type ListWorkflowResultArtifactsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	ResultID    pgtype.UUID `json:"result_id"`
}

type ListWorkflowResultArtifactsRow struct {
	ID                 pgtype.UUID        `json:"id"`
	WorkspaceID        pgtype.UUID        `json:"workspace_id"`
	WorkflowInstanceID pgtype.UUID        `json:"workflow_instance_id"`
	ArtifactID         pgtype.UUID        `json:"artifact_id"`
	ExecutionID        pgtype.UUID        `json:"execution_id"`
	ResultID           pgtype.UUID        `json:"result_id"`
	UploadID           pgtype.UUID        `json:"upload_id"`
	Revision           int32              `json:"revision"`
	SourceAttachmentID pgtype.UUID        `json:"source_attachment_id"`
	Kind               string             `json:"kind"`
	MediaType          string             `json:"media_type"`
	SchemaVersion      string             `json:"schema_version"`
	Checksum           string             `json:"checksum"`
	SizeBytes          int64              `json:"size_bytes"`
	CreatedAt          pgtype.Timestamptz `json:"created_at"`
	Name               string             `json:"name"`
	StorageKey         string             `json:"storage_key"`
}

func (q *Queries) ListWorkflowResultArtifacts(ctx context.Context, arg ListWorkflowResultArtifactsParams) ([]ListWorkflowResultArtifactsRow, error) {
	rows, err := q.db.Query(ctx, listWorkflowResultArtifacts, arg.WorkspaceID, arg.ResultID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWorkflowResultArtifactsRow{}
	for rows.Next() {
		var i ListWorkflowResultArtifactsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.WorkflowInstanceID,
			&i.ArtifactID,
			&i.ExecutionID,
			&i.ResultID,
			&i.UploadID,
			&i.Revision,
			&i.SourceAttachmentID,
			&i.Kind,
			&i.MediaType,
			&i.SchemaVersion,
			&i.Checksum,
			&i.SizeBytes,
			&i.CreatedAt,
			&i.Name,
			&i.StorageKey,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextWorkflowArtifactRevision = `-- name: NextWorkflowArtifactRevision :one
SELECT COALESCE(max(revision),0)::integer + 1 AS revision FROM workflow_artifact_revision
WHERE workspace_id=$1 AND artifact_id=$2
`

type NextWorkflowArtifactRevisionParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	ArtifactID  pgtype.UUID `json:"artifact_id"`
}

// Caller holds the Run lock for revision allocation.
func (q *Queries) NextWorkflowArtifactRevision(ctx context.Context, arg NextWorkflowArtifactRevisionParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextWorkflowArtifactRevision, arg.WorkspaceID, arg.ArtifactID)
	var revision int32
	err := row.Scan(&revision)
	return revision, err
}

